import { IngestPipeline } from "@514labs/moose-lib";

// Data model for product interaction events
export interface ProductEvent {
  event_id: string;
  event_ts: Date;
  user_id: string;
  product_id: string;
  event_type: "view" | "cart" | "purchase";
  properties: {
    page?: string;
    price?: number;
  };
}

// Configure the ingest pipeline with ClickHouse table and streaming
export const ProductEventPipeline = new IngestPipeline<ProductEvent>("ProductEvent", {
  table: {
    orderByFields: ["event_type", "event_ts", "product_id", "user_id"]
  },
  stream: true,
  ingestApi: true,
});

