import { MaterializedView } from "@514labs/moose-lib";

// Top products aggregation with view/cart/purchase counts and revenue
export interface TopProducts {
  product_id: string;
  view_count: number;
  cart_count: number;
  purchase_count: number;
  total_revenue: number;
}

export default MaterializedView<TopProducts>({
  tableName: "TopProducts",
  sourceTable: "ProductEvent",
  query: `
    SELECT
      product_id,
      countIf(event_type = 'view') as view_count,
      countIf(event_type = 'cart') as cart_count,
      countIf(event_type = 'purchase') as purchase_count,
      sumIf(toFloat64OrZero(JSONExtractString(properties, 'price')), event_type = 'purchase') as total_revenue
    FROM ProductEvent
    WHERE currentDatabase() = database()
    GROUP BY product_id
  `,
  orderByFields: ["total_revenue", "purchase_count", "product_id"]
});

