import { MaterializedView } from "@514labs/moose-lib";

// Hourly activity showing event counts per hour per event type
export interface HourlyActivity {
  event_hour: string;
  event_type: string;
  event_count: number;
}

export default MaterializedView<HourlyActivity>({
  tableName: "HourlyActivity",
  sourceTable: "ProductEvent",
  query: `
    SELECT
      formatDateTime(toStartOfHour(event_ts), '%Y-%m-%d %H:00:00') as event_hour,
      event_type,
      count(*) as event_count
    FROM ProductEvent
    WHERE currentDatabase() = database()
    GROUP BY toStartOfHour(event_ts), event_type
  `,
  orderByFields: ["event_hour", "event_type"]
});

