### Define a Custom Consumption API

Source: https://github.com/514-labs/moosestack/blob/main/apps/framework-docs-v2/content/guides/data-warehouses.mdx

Create a TypeScript API definition using the MooseStack library to query warehouse data via SQL.

```typescript
// app/apis/sales_summary.ts

import { Api } from "@514labs/moose-lib";

interface SalesSummaryParams {
  startDate: string;
  endDate: string;
}

interface SalesSummaryResult {
  date: string;
  revenue: number;
  orders: number;
  units: number;
}

export const salesSummaryApi = new Api<SalesSummaryParams, SalesSummaryResult[]>(
  "sales-summary",
  async ({ startDate, endDate }, { client, sql }) => {
    const result = await client.query.execute<SalesSummaryResult>(sql`
      SELECT
        toString(d.date) as date,
        SUM(f.total_amount) as revenue,
        COUNT(DISTINCT f.order_id) as orders,
        SUM(f.quantity) as units
      FROM fact_order_items f
      JOIN dim_date d ON f.order_date_key = d.date_key
      WHERE d.date BETWEEN ${startDate} AND ${endDate}
      GROUP BY d.date
      ORDER BY d.date
    `);

    return result.json();
  }
);
```

