import { MaterializedView } from "@514labs/moose-lib";

// Conversion funnel showing unique users and total events at each step
export interface ConversionFunnel {
  event_type: string;
  unique_users: number;
  total_events: number;
  step_order: number;
}

export const conversionFunnelView = new MaterializedView<ConversionFunnel>({
  selectStatement: `
    SELECT
      event_type,
      uniq(user_id) as unique_users,
      count(*) as total_events,
      CASE
        WHEN event_type = 'view' THEN 1
        WHEN event_type = 'cart' THEN 2
        WHEN event_type = 'purchase' THEN 3
        ELSE 4
      END as step_order
    FROM ProductEvent
    GROUP BY event_type
  `,
  tableName: "ProductEvent",
  materializedViewName: "mv_conversion_funnel",
  targetTable: {
    name: "ConversionFunnel",
    orderByFields: ["step_order"]
  }
});

