import { MaterializedView, sql } from "@514labs/moose-lib";
import { ProductEventPipeline } from "../models/ProductEvent";

// Top products aggregation with view/cart/purchase counts and revenue
export interface TopProducts {
  product_id: string;
  view_count: number;
  cart_count: number;
  purchase_count: number;
  total_revenue: number;
}

const ProductEventTable = ProductEventPipeline.table!;

export const topProductsView = new MaterializedView<TopProducts>({
  selectStatement: sql.statement`
    SELECT
      product_id,
      countIf(event_type = 'view') as view_count,
      countIf(event_type = 'cart') as cart_count,
      countIf(event_type = 'purchase') as purchase_count,
      sumIf(toFloat64OrZero(JSONExtractString(properties, 'price')), event_type = 'purchase') as total_revenue
    FROM ${ProductEventTable}
    GROUP BY product_id
  `,
  selectTables: [ProductEventTable],
  materializedViewName: "mv_top_products",
  targetTable: {
    name: "TopProducts",
    orderByFields: ["total_revenue", "purchase_count", "product_id"]
  }
});

