import { Api } from "@514labs/moose-lib";

export interface TopProductsResponse {
  product_id: string;
  view_count: number;
  cart_count: number;
  purchase_count: number;
  total_revenue: number;
}

export const topProductsApi = new Api<{}, TopProductsResponse[]>(
  "top-products",
  async ({}, { client, sql }) => {
    const result = await client.query.execute<TopProductsResponse>(sql`
      SELECT
        product_id,
        view_count,
        cart_count,
        purchase_count,
        total_revenue
      FROM TopProducts
      ORDER BY total_revenue DESC, purchase_count DESC
      LIMIT 100
    `);

    return result.json();
  }
);

