import { Api } from "@514labs/moose-lib";

export interface ConversionFunnelResponse {
  event_type: string;
  unique_users: number;
  total_events: number;
  step_order: number;
}

export const conversionFunnelApi = new Api<{}, ConversionFunnelResponse[]>(
  "conversion-funnel",
  async ({}, { client, sql }) => {
    const result = await client.query.execute<ConversionFunnelResponse>(sql`
      SELECT
        event_type,
        uniq(user_id) as unique_users,
        count(*) as total_events,
        CASE
          WHEN event_type = 'view' THEN 1
          WHEN event_type = 'cart' THEN 2
          WHEN event_type = 'purchase' THEN 3
          ELSE 4
        END as step_order
      FROM ProductEvent
      GROUP BY event_type
      ORDER BY step_order ASC
    `);

    return result.json();
  }
);

